   1	// display/lighting/sources/temporalPatterns.js
   2	// Named temporal waveform patterns for light sources.
   3	//
   4	// Each pattern is a function(t, id) → { intensity, r, g, b }
   5	//   t  = fxTime in seconds (monotonic, frame-interpolated)
   6	//   id = entity id (for per-source phase offset so identical lights desync)
   7	//
   8	// intensity: multiplier applied to light radius and brightness (0.0 – ~1.5)
   9	// r, g, b:   additive RGB shift (-1.0 to 1.0, applied as color *= 1+shift)
  10	//            Most patterns leave these at 0 (neutral).
  11	//
  12	// Usage in collectLightSources:
  13	//   const p = evaluatePattern('torch', fxTime, entityId);
  14	//   out.push({ ..., radius: base * p.intensity, flicker: p.intensity });
  15	//
  16	// CRITICAL: returns shared scratch. Caller must consume immediately or copy.
  17	
  18	/** @typedef {{ intensity: number, r: number, g: number, b: number }} PatternResult */
  19	
  20	/** Shared scratch object — avoids allocation per evaluation. */
  21	const _result = { intensity: 1, r: 0, g: 0, b: 0 };
  22	
  23	/** Return the scratch result with given values. */
  24	function out(intensity, r, g, b) {
  25	  _result.intensity = intensity;
  26	  _result.r = r; _result.g = g; _result.b = b;
  27	  return _result;
  28	}
  29	
  30	// ---- Pattern definitions --------------------------------------------------
  32	/**
  33	 * Torch — warm, organic flicker. Slow sway + medium wobble + shimmer + jitter.
  34	 * Deeper troughs: range ~0.50 – 1.10. Same peak brightness, dips much lower.
  35	 */
  36	function torch(t, id) {
  37	  const v = 0.80
  38	    + 0.15 * Math.sin(t * 1.4  + id)
  39	    + 0.09 * Math.sin(t * 3.1  + id * 0.7)
  40	    + 0.06 * Math.sin(t * 5.9)
  41	    + 0.06 * (Math.random() - 0.5);
  42	  return out(v, 0, 0, 0);
  43	}
  44	
  45	/**
  46	 * Ember — slow smolder with occasional bright flare.
  47	 * Base sits at ~0.75, punctuated by brief bright peaks.
  48	 * Good for dying fires, furnaces cooling down, fire pits.
  49	 * Range: ~0.67 – 1.12.
  50	 */
  51	function ember(t, id) {
  52	  const phase = t * 0.8 + id * 1.3;
  53	  const base = 0.75 + 0.08 * Math.sin(phase);
  54	  // Flare: narrow bright spike every ~4 seconds (per-entity offset)
  55	  const flareCycle = (t * 0.25 + id * 0.37) % 1.0;
  56	  const flare = flareCycle > 0.85 ? (flareCycle - 0.85) / 0.15 : 0;
  57	  const flareShape = flare * flare * (3 - 2 * flare);  // smoothstep
  58	  const v = base + flareShape * 0.35;
  59	  // Slight red shift during flare
  60	  return out(v, flareShape * 0.12, -flareShape * 0.04, -flareShape * 0.06);
  61	}
  62	
  63	/**
  64	 * Breathe — very slow sinusoidal swell. Calm, meditative.
  65	 * Good for altars, shrines, sleeping enchantments.
  66	 * Range: ~0.5 – 1.0.
  67	 */
  68	function breathe(t, id) {
  69	  const phase = t * 0.4 + id * 2.1;
  70	  const v = 0.85 + 0.15 * Math.sin(phase);
  71	  return out(v, 0, 0, 0);
  72	}
  73	
  74	/**
  75	 * Occult — irregular, unsettling rhythm. Phase-shifted harmonics that
  76	 * never quite settle into a pattern. Feels wrong.
  77	 * Good for cursed objects, shadow magic, void artifacts.
  78	 * Range: ~0.62 – 1.02.
  79	 */
  80	function occult(t, id) {
  81	  const p = id * 0.91;
  82	  const v = 0.82
  83	    + 0.10 * Math.sin(t * 1.1 + p)
  84	    + 0.07 * Math.sin(t * 1.7 + p * 1.3)
  85	    + 0.05 * Math.sin(t * 2.9 + p * 0.5)
  86	    + 0.04 * Math.sin(t * 4.3 + p * 2.1);
  87	  // Subtle purple-shift
  88	  return out(v, -0.04, -0.06, 0.05);
  89	}
  90	
  91	/**
  92	 * Pulse — steady metronome. Bright peak with dimmer rest.
  93	 * Period ~2 seconds. Good for mechanical, magical, or divine sources.
  94	 * Range: 0.65 – 1.0.
  95	 */
  96	function pulse(t, id) {
  97	  const phase = (t * 0.5 + id * 0.73) % 1.0;
  98	  // Smooth pulse: steep rise, brief hold, steep fall
  99	  let v;
 100	  if (phase < 0.15)      v = phase / 0.15;                        // rise
 101	  else if (phase < 0.35) v = 1.0;                                 // hold
 102	  else if (phase < 0.50) v = 1.0 - (phase - 0.35) / 0.15;        // fall
 103	  else                   v = 0.0;                                  // off
 104	  v = v * v * (3 - 2 * v);  // smoothstep the transitions
 105	  return out(0.65 + v * 0.35, 0, 0, 0);
 106	}
 107	
 108	/**
 109	 * Portal — stable blue ring with a slow breathing tide and soft edge shimmer.
 110	 * Calmer than a rift, suited to return portals and controlled transitions.
 111	 * Range: ~0.76 - 1.04.
 112	 */
 113	function portal(t, id) {
 114	  const p = id * 0.61;
 115	  const tide = 0.88 + 0.11 * Math.sin(t * 0.82 + p);
 116	  const edge = 0.03 * Math.sin(t * 5.4 + p * 1.7)
 117	    + 0.02 * Math.sin(t * 8.2 + p * 0.4);
 118	  const shimmer = Math.max(0, edge);
 119	  return out(tide + edge, -0.04 - shimmer * 0.10, 0.02 + shimmer * 0.04, 0.07 + shimmer * 0.12);
 120	}
