 * @param {number} depth
 * @returns {Object|null}
 */
export function pickSpecificMonster(monsterId, depth) {
  const def = getMonster(monsterId);
  if (!def || def.disabled || isGenocided(monsterId)) return null;
  return toMonsterSpawnParams(def, depth);
}

