function findNearestRival(world, selfId, ox, oy, sightRange, isBlocked) {
  let best = null;
  let bestDist = Infinity;
  forEachInRadius(world, ox, oy, sightRange, (id, pos) => {
    if (id === selfId) return;
    const fac = world.get(id, Faction);
