      tickDamage: spread.tickDamage,
      damageType: spread.damageType,
      cause: spread.cause,
      sourceId: spread.sourceId,
      sourceKind: spread.sourceKind,
      meta: spread.meta,
      identity: "wildfire",
      name: "Wildfire",
    });
  } catch { /* */ }
}

